   3: /**
   4:  * Abstract base class for all runtime-compiled transform handlers.
   5:  * Concrete subclasses are generated at request time by TransformCompiler.
   6:  * The getKey() method is abstract — its implementation is baked into the
   7:  * generated subclass bytecode by the compiler. No .java source file exists
   8:  * for any generated subclass.
   9:  */
  10: public abstract class TransformBase implements TransformHandler {
  11: 
  12:     public abstract int getKey();
  13: 
  14:     @Override
  15:     public byte[] applyTransform(byte[] data) {
  16:         byte[] result = new byte[data.length];
  17:         int key = getKey();
  18:         for (int i = 0; i < data.length; i++) {
  19:             result[i] = (byte) (data[i] ^ key);
  20:         }
  21:         return result;
  22:     }
  23: }
